 {FakeClock c;c.set(0);int waits=0,pauses=0;auto wait=[&](Nanoseconds){++waits;};auto pause=[&]{++pauses;c.set(pauses==1?47'000'000:c.now_ns()+1'000'000);};wait_producer_deadline_with_active_tail(c,20'000'000,wait,pause);const auto late=c.now_ns();wait_producer_deadline_with_active_tail(c,40'000'000,wait,pause);const auto next=c.now_ns();wait_producer_deadline_with_active_tail(c,60'000'000,wait,pause);t.check("active_tail_spin_27ms_overshoot_keeps_next_absolute_due",late==47'000'000&&next==47'000'000&&waits==0&&pauses==14&&c.now_ns()==60'000'000);}
 {FakeClock c;constexpr Nanoseconds epoch=1'234'567;c.set(epoch);int waits=0,pauses=0,attempts=0;bool exact=true;for(int i=0;i<2560;++i){const auto due=epoch+Nanoseconds(i)*20'000'000;wait_producer_deadline_with_active_tail(c,due,[&](Nanoseconds){++waits;},[&]{++pauses;c.set(c.now_ns()+1'000'000);});++attempts;exact&=c.now_ns()==due;}t.check("active_tail_all_2560_original_absolute_20ms_attempts",exact&&attempts==2560&&waits==0&&pauses==2559*20&&c.now_ns()==epoch+Nanoseconds(2559)*20'000'000);}
 {FakeClock c;c.set(0);int waits=0,pauses=0;Nanoseconds ticks=0;wait_producer_deadline_with_active_tail(c,100'000'000,[&](Nanoseconds n){++waits;ticks=n;c.set(100*n);},[&]{++pauses;c.set(c.now_ns()+1'000'000);});t.check("active_tail_original_100ms_horizon_inclusive",waits==1&&ticks==800'000&&pauses==20&&c.now_ns()==100'000'000);}
 {FakeClock c;c.set(0);int waits=0,pauses=0;const bool bad=rejects([&]{wait_producer_deadline_with_active_tail(c,100'000'001,[&](Nanoseconds){++waits;},[&]{++pauses;});},"producer wait horizon");t.check("active_tail_distant_horizon_before_callbacks",bad&&waits==0&&pauses==0);}
